namespace Rainmaker.Axis;
internal static class AxisInteraction150Tests
{
 internal static void Run(string root)
 {
  void Check(bool condition,string message){if(!condition)throw new Exception(message);}
  var db=Autodesk.AutoCAD.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument.Database;
  var library=new AxisLibrary(Plugin.Current!.Config.ContentRoot);var settings=library.Load();
  var window=new AxisGridDialog(60);object Field(string name)=>typeof(AxisGridDialog).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(window)!;object? Call(string name,params object[] args)=>typeof(AxisGridDialog).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,args);AxisGridParameters Read()=>(AxisGridParameters)Call("Read")!;void Update()=>Call("UpdateState");
  ((TextBox)Field("xBays")).Text="4000 4000 4000 5000 6000";((TextBox)Field("yBays")).Text="4000 4000 3000";Update();((CheckBox)Field("columnsOn")).IsChecked=true;((CheckBox)Field("wallsOn")).IsChecked=true;Update();var p=Read();var geometry=ConstructionGeometry.Make(p,new());
  Check(geometry.Columns.Count==24&&geometry.Columns.Single(c=>c.Key=="0:0").Center.X==40&&geometry.Columns.Single(c=>c.Key=="0:0").Center.Y==40,"Initial automatic boundary anchor keeps faces 110 from axes");Check(geometry.Columns.Single(c=>c.Key=="2:1").Center.X==8000&&geometry.Columns.Single(c=>c.Key=="2:1").Center.Y==4000,"Interior columns stay on grid intersections");
  var view=(FrameworkElement)window.Content;void Render(string? filename=null){view.Measure(new Size(1640,910));view.Arrange(new Rect(0,0,1640,910));view.UpdateLayout();view.Dispatcher.Invoke(System.Windows.Threading.DispatcherPriority.DataBind,new Action(()=>{}));var bmp=new RenderTargetBitmap(1640,910,96,96,PixelFormats.Pbgra32);bmp.Render(view);if(filename!=null){var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using var output=File.Create(Path.Combine(root,filename));png.Save(output);}}
  Render();var preview=(AxisPreview)Field("preview");var board=(Grid)Field("board");double ratio=board.ColumnDefinitions[0].ActualWidth/board.ColumnDefinitions[2].ActualWidth;Check(Math.Abs(ratio-3.0/7)<.02,"Default layout is 30/70");
  string ui=Path.Combine(root,"axis-ui-fixture.json");AxisUiState.SaveRatio(ui,.61);Check(Math.Abs(AxisUiState.ReadRatio(ui)-.61)<1e-10,"New settings reader restores last splitter ratio after restart");Check(AxisUiState.ReadRatio(Path.Combine(root,"missing-ui.json"))==AxisUiState.DefaultRatio,"New machine defaults to 30/70");
  preview.PickMode="Columns";var hit=preview.Hits.Single(h=>h.Kind=="Columns"&&h.Key=="2:1");var partial=new Rect(hit.Bounds.Left-2,hit.Bounds.Top-2,Math.Max(1,hit.Bounds.Width*.6),hit.Bounds.Height+4);preview.SelectRectangle(partial,false,false);Check(!preview.PickedColumns.Contains(hit.Key),"Left-to-right does not select partial column");preview.SelectRectangle(partial,false,true);Check(preview.PickedColumns.Contains(hit.Key),"Right-to-left selects intersecting column");var full=hit.Bounds;full.Inflate(2,2);preview.SelectRectangle(full,false,false);Check(preview.PickedColumns.Contains(hit.Key),"Window fully encloses selected column");
  ((ComboBox)Field("columnAnchor")).SelectedItem="WallTopRight";((TextBox)Field("columnRotation")).Text="90";Update();p=Read();var c=ConstructionGeometry.Make(p,new()).Columns.Single(x=>x.Key==hit.Key);Check(c.Center.X==8040&&c.Center.Y==4040,"Wall anchor stays in grid coordinates when section rotates");Render();var mark=preview.ColumnAxisMarks.Single(m=>m.Key==hit.Key);Check(Math.Abs(mark.X.X-mark.Origin.X)<.01&&mark.X.Y<mark.Origin.Y&&mark.Y.X<mark.Origin.X,"Xc/Yc rotate with section at 90 degrees");((CheckBox)Field("showColumnAxes")).IsChecked=false;Render();Check(preview.ColumnAxisMarks.Count==0,"Direction arrows can be hidden");((CheckBox)Field("showColumnAxes")).IsChecked=true;
  preview.PickMode="Walls";Render();hit=preview.Hits.First(h=>h.Kind=="Walls"&&h.Key=="X:2:0");partial=new Rect(hit.Bounds.Left+hit.Bounds.Width*.4,hit.Bounds.Top-1,Math.Max(1,hit.Bounds.Width*.2),hit.Bounds.Height+2);preview.SelectRectangle(partial,false,false);Check(!preview.PickedWalls.Contains(hit.Key),"Window does not select partial wall");preview.SelectRectangle(partial,false,true);Check(preview.PickedWalls.Contains(hit.Key),"Crossing selects actual wall footprint");
  ((TextBox)Field("wallThickness")).Text="110";Update();p=Read();geometry=ConstructionGeometry.Make(p,new());Check(Math.Abs(geometry.Walls.Single(w=>w.Key=="X:2:0").Corners.Min(v=>v.Y)+110)<1e-6,"Thinner perimeter wall keeps exterior face aligned");
  int builds=preview.BooleanBuilds;var before=preview.Pan;preview.BeginPan(new Point(20,30));preview.MovePan(new Point(50,70));preview.EndPan();Check(preview.Pan==before+new Vector(30,40),"Middle-pan helper applies correct delta");var watch=Stopwatch.StartNew();for(int i=0;i<12;i++){preview.ZoomAt(i%2==0?1.02:1/1.02,new Point(300,200));Render();}double renderMs=watch.Elapsed.TotalMilliseconds;Check(preview.BooleanBuilds==builds,"Pan/zoom repaints reuse flattened wall geometry");Update();Check(preview.BooleanBuilds==builds,"Unchanged input/selection does not rebuild wall booleans");Check(renderMs<10000,"12 redraws must stay below ten seconds on native test machine: "+renderMs);
  // Reproduce the old protruding end with a 220/110 L joint, then verify exact new outer extents.
  var joint=new AxisGridParameters{XBays=new[]{4000.0},YBays=new[]{3000.0},XLabels=new[]{"1","2"},YLabels=new[]{"A","B"},Scale=60,Walls=true,WallSegments=new[]{"X:0:0","Y:1:0"},DirectedWalls=true};joint.WallOverrides["Y:1:0"]=new(){Thickness=110};var old=ConstructionGeometry.Make(joint,new());Check(old.Walls.Single(w=>w.Key=="Y:1:0").Corners.Min(v=>v.Y)==-55,"Old square cap reproduction");joint.CleanWallJunctions=true;var fixedJoint=ConstructionGeometry.Make(joint,new());var loops=ConstructionWriter.WallLoops(fixedJoint);try{Check(loops.Count==1&&loops.All(l=>l.Closed),"Mixed-width L joint produces one closed boundary");Check(loops.Max(l=>l.GeometricExtents.MaxPoint.X)<=4110.00001&&loops.Min(l=>l.GeometricExtents.MinPoint.Y)>=-110.00001,"L corner has no overrun past exterior faces");}finally{foreach(var loop in loops)loop.Dispose();}
  // Collinear pieces share a face, no internal end cap or seam; T/X join without crossing the outer wall.
  joint.XBays=new[]{2000.0,2000};joint.XLabels=new[]{"1","2","3"};joint.WallSegments=new[]{"X:0:0","X:1:0","Y:1:0"};joint.WallOverrides.Clear();joint.WallOverrides["X:1:0"]=new(){Thickness=110};joint.WallOverrides["Y:1:0"]=new(){Thickness=330};var tee=ConstructionGeometry.Make(joint,new());loops=ConstructionWriter.WallLoops(tee);try{Check(loops.Count==1&&loops.Single().Closed,"Mixed-width T and collinear join has one closed outline");Check(loops.Single().GeometricExtents.MinPoint.Y>=-110.00001,"Thick T branch does not protrude beyond perimeter");}finally{foreach(var loop in loops)loop.Dispose();}
  joint.WallSegments=new[]{"X:0:0","X:1:0"};loops=ConstructionWriter.WallLoops(ConstructionGeometry.Make(joint,new()));try{Check(loops.Count==1&&loops.Single().Closed,"Collinear pieces unite without internal end seam");}finally{foreach(var loop in loops)loop.Dispose();}
  var lib=library.Resolve(settings,false);library.ResolveConstruction(lib,p);var managed=GridStore.Apply(db,lib,p,new Point3d(1500000,0,0),null,false,true);var cheap=GridStore.List(db,false);Check(cheap.All(r=>r.Definition==null||r.Status=="Chọn để đối chiếu"),"Opening catalog does not hash every grid's members");watch.Restart();Call("LoadDefinition",managed);double loadMs=watch.Elapsed.TotalMilliseconds;Check(GridStore.Changes(db,managed).Count==0&&preview.Existing!=null&&preview.Existing.Paths.Count>0,"Selected grid still verifies edits and captures real geometry");
  // Pick arrows for the screenshot; remaining preview can pan without reading DWG/hatch again.
  Render();preview.PickMode="Columns";preview.SelectAt(preview.Project(new(8110,4110)));Update();Render("axis150-preview.png");
  var name=(TextBox)Field("gridName");var rename=Descendants(view).OfType<Button>().First(b=>Equals(b.Content,"Đổi tên"));double bottomName=name.TranslatePoint(new Point(0,name.ActualHeight),view).Y,bottomButton=rename.TranslatePoint(new Point(0,rename.ActualHeight),view).Y;Check(Math.Abs(bottomName-bottomButton)<2,"Rename actions align to name field bottom");window.Close();
  string drawing=Path.Combine(root,"axis150-output.dwg");db.SaveAs(drawing,DwgVersion.AC1032);using(var reopened=new Database(false,true)){reopened.ReadDwgFile(drawing,FileOpenMode.OpenForReadAndAllShare,true,"");var restored=GridStore.Read(reopened,GridStore.HandleId(reopened,managed.Members.Keys.First()))!;Check(restored.Parameters.ColumnOverrides["2:1"].Anchor=="WallTopRight"&&restored.Parameters.CleanWallJunctions&&GridStore.Changes(reopened,restored).Count==0,"Save/reopen retains new anchors, clean junctions and stable fingerprints");}
  JsonUtil.Atomic(Path.Combine(root,"axis150-results.json"),new{passed=true,autoInset110=true,windowCrossingColumns=true,windowCrossingWalls=true,rotatedLocalArrows=true,middlePan=true,cachedBooleanRepaint=true,default30to70=true,splitPersistence=true,alignedRename=true,mixedWidthJunctions=true,lazyCatalog=true,saveReopen=true,redraw12Milliseconds=renderMs,selectedGridLoadMilliseconds=loadMs,geometryBooleanBuilds=preview.BooleanBuilds});
 }
 static System.Collections.Generic.IEnumerable<DependencyObject> Descendants(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var nested in Descendants(child))yield return nested;}}
}
